288	    private String normalizeTelephone(String telephone) {
289	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
290	        String digits;
291	        if (cleaned.startsWith("+")) {
292	            digits = cleaned.substring(1);
293	        } else {
294	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
295	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
296	            digits = "61" + national;
297	        }
298	        if (!digits.matches("[0-9]{8,15}")) {
299	            throw new InvalidTelephoneException(cleaned);
300	        }
301	        return "+" + digits;
302	    }
